import json,sys
from collections import defaultdict
sys.path.insert(0,'/app/task_file/scripts')
from cost_model import *

def build(rs, keyfn, shp):
    groups=defaultdict(list)
    for r in rs: groups[keyfn(r)].append(r)
    plan=[]
    for i,(k,grp) in enumerate(sorted(groups.items(), key=lambda x:str(x[0]))):
        for r in grp:
            plan.append({'request_id':r['request_id'],'batch_id':'b-%05d'%i,'shape':{'seq_align':shp,'heads_align':32,'hidden_align':4096}})
    return plan

def report(name,rs,plan):
    cm=CostModel(64); req={r['request_id']:r for r in rs}
    m=cm.plan_metrics(req,plan); nb=len(set(p['batch_id'] for p in plan))
    print('%-30s cost=%.4e pad=%.4f p95=%.4e seq=%.4e nb=%d'%(name,m['cost'],m['pad_ratio'],m['p95_latency_ms'],m['sequential_timecost'],nb))
    return m

for f,shp in [('/app/task_file/input_data/requests_bucket_1.jsonl',2048),('/app/task_file/input_data/requests_bucket_2.jsonl',704)]:
    rs=[json.loads(l) for l in open(f)]
    print('===',f)
    for k in [1,2,3,4,5,6,8,12,16,24,32,48,64]:
        report('S exact, G//%d'%k, rs, build(rs, lambda r,k=k:(align(r['prompt_len'],64),(r['gen_len']+k-1)//k*k), shp))
